void PTv3TRT::allocateMessages()
{
  if (segmented_points_msg_ptr_ == nullptr) {
    segmented_points_msg_ptr_ = std::make_unique<cuda_blackboard::CudaPointCloud2>();
    segmented_points_msg_ptr_->height = 1;
    segmented_points_msg_ptr_->width = config_.max_num_voxels_;
    segmented_points_msg_ptr_->fields = segmented_pointcloud_fields_;
    segmented_points_msg_ptr_->is_bigendian = false;
    segmented_points_msg_ptr_->is_dense = true;
    segmented_points_msg_ptr_->point_step = 17U;
    segmented_points_msg_ptr_->data = cuda_blackboard::make_unique<std::uint8_t[]>(
      config_.max_num_voxels_ * segmented_points_msg_ptr_->point_step);
  }

  if (visualization_points_msg_ptr_ == nullptr) {
    visualization_points_msg_ptr_ = std::make_unique<cuda_blackboard::CudaPointCloud2>();
    visualization_points_msg_ptr_->height = 1;
    visualization_points_msg_ptr_->width = config_.max_num_voxels_;
    visualization_points_msg_ptr_->fields = visualization_pointcloud_fields_;
    visualization_points_msg_ptr_->is_bigendian = false;
    visualization_points_msg_ptr_->is_dense = true;
    visualization_points_msg_ptr_->point_step =
      static_cast<std::uint32_t>(visualization_pointcloud_fields_.size() * sizeof(float));
    visualization_points_msg_ptr_->data = cuda_blackboard::make_unique<std::uint8_t[]>(
      config_.max_num_voxels_ * visualization_points_msg_ptr_->point_step);
  }

  if (filtered_points_msg_ptr_ == nullptr && filtered_output_format_ != CloudFormat::UNKNOWN) {
    filtered_points_msg_ptr_ = std::make_unique<cuda_blackboard::CudaPointCloud2>();
    filtered_points_msg_ptr_->height = 1;
    filtered_points_msg_ptr_->width = config_.max_num_voxels_;
    filtered_points_msg_ptr_->fields = filtered_pointcloud_fields_;
    filtered_points_msg_ptr_->is_bigendian = false;
    filtered_points_msg_ptr_->is_dense = true;
    filtered_points_msg_ptr_->point_step =
      static_cast<std::uint32_t>(get_point_step(filtered_output_format_));
    filtered_points_msg_ptr_->data = cuda_blackboard::make_unique<std::uint8_t[]>(
      config_.max_num_voxels_ * filtered_points_msg_ptr_->point_step);
  }
}

inline std::size_t get_point_step(CloudFormat format)
{
  switch (format) {
    case CloudFormat::XYZIRCAEDT:
      return sizeof(CloudPointTypeXYZIRCAEDT);
    case CloudFormat::XYZIRADRT:
      return sizeof(CloudPointTypeXYZIRADRT);
    case CloudFormat::XYZIRC:
      return sizeof(CloudPointTypeXYZIRC);
    case CloudFormat::XYZI:
      return sizeof(CloudPointTypeXYZI);
    default:
      return 0;
  }
}

std::size_t PreprocessCuda::generateFeatures(
  const void * input_data, CloudFormat input_format, unsigned int num_points,
  float * voxel_features, std::int64_t * voxel_coords, std::int64_t * voxel_hashes,
  void * compact_points)
{
  auto policy = thrust::cuda::par.on(stream_);

  const auto num_blocks = divup(num_points, config_.threads_per_block_);
  switch (input_format) {
    case CloudFormat::XYZIRCAEDT:
      points2FeaturesKernel<<<num_blocks, config_.threads_per_block_, 0, stream_>>>(
        static_cast<const CloudPointTypeXYZIRCAEDT *>(input_data), num_points,
        reinterpret_cast<float4 *>(points_d_.get()));
      break;
    case CloudFormat::XYZIRADRT:
      points2FeaturesKernel<<<num_blocks, config_.threads_per_block_, 0, stream_>>>(
        static_cast<const CloudPointTypeXYZIRADRT *>(input_data), num_points,
        reinterpret_cast<float4 *>(points_d_.get()));
      break;
    case CloudFormat::XYZIRC:
      points2FeaturesKernel<<<num_blocks, config_.threads_per_block_, 0, stream_>>>(
        static_cast<const CloudPointTypeXYZIRC *>(input_data), num_points,
        reinterpret_cast<float4 *>(points_d_.get()));
      break;
    case CloudFormat::XYZI:
      points2FeaturesKernel<<<num_blocks, config_.threads_per_block_, 0, stream_>>>(
        static_cast<const CloudPointTypeXYZI *>(input_data), num_points,
        reinterpret_cast<float4 *>(points_d_.get()));
      break;
    default:
      throw std::runtime_error("Unsupported input point cloud format.");
  }

  cropKernel<<<num_blocks, config_.threads_per_block_, 0, stream_>>>(
    reinterpret_cast<float4 *>(points_d_.get()), crop_mask_d_.get(), num_points,
    config_.min_x_range_, config_.min_y_range_, config_.min_z_range_, config_.max_x_range_,
    config_.max_y_range_, config_.max_z_range_);

  thrust::inclusive_scan(
    policy, crop_mask_d_.get(), crop_mask_d_.get() + num_points, crop_indices_d_.get());

  std::uint32_t num_cropped_points;

  cudaMemcpyAsync(
    &num_cropped_points, crop_indices_d_.get() + num_points - 1, sizeof(std::uint32_t),
    cudaMemcpyDeviceToHost, stream_);
  CHECK_CUDA_ERROR(cudaStreamSynchronize(stream_));

  if (num_cropped_points == 0) {
    return 0;
  }

  extractIndicesKernel<<<num_blocks, config_.threads_per_block_, 0, stream_>>>(
    reinterpret_cast<float4 *>(points_d_.get()), crop_mask_d_.get(), crop_indices_d_.get(),
    reinterpret_cast<float4 *>(cropped_points_d_.get()), num_points);

  switch (input_format) {
    case CloudFormat::XYZIRCAEDT:
      extractIndicesKernel<<<num_blocks, config_.threads_per_block_, 0, stream_>>>(
        static_cast<const CloudPointTypeXYZIRCAEDT *>(input_data), crop_mask_d_.get(),
        crop_indices_d_.get(),
        reinterpret_cast<CloudPointTypeXYZIRCAEDT *>(cropped_input_points_d_.get()), num_points);
      break;
    case CloudFormat::XYZIRADRT:
      extractIndicesKernel<<<num_blocks, config_.threads_per_block_, 0, stream_>>>(
        static_cast<const CloudPointTypeXYZIRADRT *>(input_data), crop_mask_d_.get(),
        crop_indices_d_.get(),
        reinterpret_cast<CloudPointTypeXYZIRADRT *>(cropped_input_points_d_.get()), num_points);
      break;
    case CloudFormat::XYZIRC:
      extractIndicesKernel<<<num_blocks, config_.threads_per_block_, 0, stream_>>>(
        static_cast<const CloudPointTypeXYZIRC *>(input_data), crop_mask_d_.get(),
        crop_indices_d_.get(),
        reinterpret_cast<CloudPointTypeXYZIRC *>(cropped_input_points_d_.get()), num_points);
      break;
    case CloudFormat::XYZI:
      extractIndicesKernel<<<num_blocks, config_.threads_per_block_, 0, stream_>>>(
        static_cast<const CloudPointTypeXYZI *>(input_data), crop_mask_d_.get(),
        crop_indices_d_.get(),
        reinterpret_cast<CloudPointTypeXYZI *>(cropped_input_points_d_.get()), num_points);
      break;
    default:
      throw std::runtime_error("Unsupported input point cloud format.");
  }

  auto min_op = [] __host__ __device__(const float4 & a, const float4 & b) {
    return make_float4(fminf(a.x, b.x), fminf(a.y, b.y), fminf(a.z, b.z), fminf(a.w, b.w));
  };

  auto max_op = [] __host__ __device__(const float4 & a, const float4 & b) {
    return make_float4(fmaxf(a.x, b.x), fmaxf(a.y, b.y), fmaxf(a.z, b.z), fmaxf(a.w, b.w));
  };

  float4 min_value = make_float4(
    std::numeric_limits<float>::max(), std::numeric_limits<float>::max(),
    std::numeric_limits<float>::max(), std::numeric_limits<float>::max());
  min_value = thrust::reduce(
    policy, reinterpret_cast<float4 *>(cropped_points_d_.get()),
    reinterpret_cast<float4 *>(cropped_points_d_.get()) + num_cropped_points, min_value, min_op);

  float4 max_value = make_float4(
    -std::numeric_limits<float>::max(), -std::numeric_limits<float>::max(),
    -std::numeric_limits<float>::max(), -std::numeric_limits<float>::max());
  max_value = thrust::reduce(
    policy, reinterpret_cast<float4 *>(cropped_points_d_.get()),
    reinterpret_cast<float4 *>(cropped_points_d_.get()) + num_cropped_points, max_value, max_op);

  std::int32_t min_x = static_cast<std::int32_t>(std::floor(min_value.x / config_.voxel_x_size_));
  std::int32_t min_y = static_cast<std::int32_t>(std::floor(min_value.y / config_.voxel_y_size_));
  std::int32_t min_z = static_cast<std::int32_t>(std::floor(min_value.z / config_.voxel_z_size_));

  const auto num_cropped_blocks = divup(num_cropped_points, config_.threads_per_block_);

  std::uint64_t num_unique_points;

  if (config_.use_64bit_hash_) {
    voxelizationHash64Kernel<<<num_cropped_blocks, config_.threads_per_block_, 0, stream_>>>(
      reinterpret_cast<float4 *>(cropped_points_d_.get()), hashes64_d_.get(), num_cropped_points,
      config_.voxel_x_size_, config_.voxel_y_size_, config_.voxel_z_size_, min_x, min_y, min_z);

    cub::DeviceRadixSort::SortPairs(
      reinterpret_cast<void *>(sort_workspace_d_.get()), sort_workspace_size_, hashes64_d_.get(),
      sorted_hashes64_d_.get(), hash_indexes64_d_.get(), sorted_hash_indexes64_d_.get(),
      num_cropped_points, 0, 64, stream_);

    auto not_equal = [] __device__(const std::uint64_t a, const std::uint64_t b) { return a != b; };

    thrust::adjacent_difference(
      policy, sorted_hashes64_d_.get(), sorted_hashes64_d_.get() + num_cropped_points,
      unique_mask64_d_.get(), not_equal);

    std::uint64_t one = 1;
    cudaMemcpyAsync(
      unique_mask64_d_.get(), &one, sizeof(std::uint64_t), cudaMemcpyHostToDevice, stream_);

    thrust::inclusive_scan(
      policy, unique_mask64_d_.get(), unique_mask64_d_.get() + num_cropped_points,
      unique_indices64_d_.get());

    cudaMemcpyAsync(
      &num_unique_points, unique_indices64_d_.get() + num_cropped_points - 1, sizeof(std::int64_t),
      cudaMemcpyDeviceToHost, stream_);

    extractIndicesKernel<<<num_cropped_blocks, config_.threads_per_block_, 0, stream_>>>(
      reinterpret_cast<float4 *>(cropped_points_d_.get()), unique_mask64_d_.get(),
      unique_indices64_d_.get(), sorted_hash_indexes64_d_.get(),
      reinterpret_cast<float4 *>(voxel_features), num_cropped_points);

    switch (input_format) {
      case CloudFormat::XYZIRCAEDT:
        extractIndicesKernel<<<num_cropped_blocks, config_.threads_per_block_, 0, stream_>>>(
          reinterpret_cast<CloudPointTypeXYZIRCAEDT *>(cropped_input_points_d_.get()),
          unique_mask64_d_.get(), unique_indices64_d_.get(), sorted_hash_indexes64_d_.get(),
          reinterpret_cast<CloudPointTypeXYZIRCAEDT *>(compact_points), num_cropped_points);
        break;
      case CloudFormat::XYZIRADRT:
        extractIndicesKernel<<<num_cropped_blocks, config_.threads_per_block_, 0, stream_>>>(
          reinterpret_cast<CloudPointTypeXYZIRADRT *>(cropped_input_points_d_.get()),
          unique_mask64_d_.get(), unique_indices64_d_.get(), sorted_hash_indexes64_d_.get(),
          reinterpret_cast<CloudPointTypeXYZIRADRT *>(compact_points), num_cropped_points);
        break;
      case CloudFormat::XYZIRC:
        extractIndicesKernel<<<num_cropped_blocks, config_.threads_per_block_, 0, stream_>>>(
          reinterpret_cast<CloudPointTypeXYZIRC *>(cropped_input_points_d_.get()),
          unique_mask64_d_.get(), unique_indices64_d_.get(), sorted_hash_indexes64_d_.get(),
          reinterpret_cast<CloudPointTypeXYZIRC *>(compact_points), num_cropped_points);
        break;
      case CloudFormat::XYZI:
        extractIndicesKernel<<<num_cropped_blocks, config_.threads_per_block_, 0, stream_>>>(
          reinterpret_cast<CloudPointTypeXYZI *>(cropped_input_points_d_.get()),
          unique_mask64_d_.get(), unique_indices64_d_.get(), sorted_hash_indexes64_d_.get(),
          reinterpret_cast<CloudPointTypeXYZI *>(compact_points), num_cropped_points);
        break;
      default:
        throw std::runtime_error("Unsupported input point cloud format.");
    }

  } else {
    voxelizationHash32Kernel<<<num_cropped_blocks, config_.threads_per_block_, 0, stream_>>>(
      reinterpret_cast<float4 *>(cropped_points_d_.get()), hashes32_d_.get(), num_cropped_points,
      config_.voxel_x_size_, config_.voxel_y_size_, config_.voxel_z_size_, config_.min_x_range_,
      config_.min_y_range_, config_.min_z_range_, static_cast<std::uint32_t>(config_.grid_x_size_),
      static_cast<std::uint32_t>(config_.grid_x_size_ * config_.grid_y_size_));

    cub::DeviceRadixSort::SortPairs(
      reinterpret_cast<void *>(sort_workspace_d_.get()), sort_workspace_size_, hashes32_d_.get(),
      sorted_hashes32_d_.get(), hash_indexes32_d_.get(), sorted_hash_indexes32_d_.get(),
      num_cropped_points, 0, 32, stream_);

    auto not_equal = [] __device__(const std::uint32_t a, const std::uint32_t b) { return a != b; };

    thrust::adjacent_difference(
      policy, sorted_hashes32_d_.get(), sorted_hashes32_d_.get() + num_cropped_points,
      unique_mask32_d_.get(), not_equal);

    std::uint32_t one = 1;
    cudaMemcpyAsync(
      unique_mask32_d_.get(), &one, sizeof(std::uint32_t), cudaMemcpyHostToDevice, stream_);

    thrust::inclusive_scan(
      policy, unique_mask32_d_.get(), unique_mask32_d_.get() + num_cropped_points,
      unique_indices32_d_.get());

    std::uint32_t num_unique_points32;
    cudaMemcpyAsync(
      &num_unique_points32, unique_indices32_d_.get() + num_cropped_points - 1,
      sizeof(std::uint32_t), cudaMemcpyDeviceToHost, stream_);
    CHECK_CUDA_ERROR(cudaStreamSynchronize(stream_));

    num_unique_points = static_cast<std::uint64_t>(num_unique_points32);

    extractIndicesKernel<<<num_cropped_blocks, config_.threads_per_block_, 0, stream_>>>(
      reinterpret_cast<float4 *>(cropped_points_d_.get()), unique_mask32_d_.get(),
      unique_indices32_d_.get(), sorted_hash_indexes32_d_.get(),
      reinterpret_cast<float4 *>(voxel_features), num_cropped_points);

    switch (input_format) {
      case CloudFormat::XYZIRCAEDT:
        extractIndicesKernel<<<num_cropped_blocks, config_.threads_per_block_, 0, stream_>>>(
          reinterpret_cast<CloudPointTypeXYZIRCAEDT *>(cropped_input_points_d_.get()),
          unique_mask32_d_.get(), unique_indices32_d_.get(), sorted_hash_indexes32_d_.get(),
          reinterpret_cast<CloudPointTypeXYZIRCAEDT *>(compact_points), num_cropped_points);
        break;
      case CloudFormat::XYZIRADRT:
        extractIndicesKernel<<<num_cropped_blocks, config_.threads_per_block_, 0, stream_>>>(
          reinterpret_cast<CloudPointTypeXYZIRADRT *>(cropped_input_points_d_.get()),
          unique_mask32_d_.get(), unique_indices32_d_.get(), sorted_hash_indexes32_d_.get(),
          reinterpret_cast<CloudPointTypeXYZIRADRT *>(compact_points), num_cropped_points);
        break;
      case CloudFormat::XYZIRC:
        extractIndicesKernel<<<num_cropped_blocks, config_.threads_per_block_, 0, stream_>>>(
          reinterpret_cast<CloudPointTypeXYZIRC *>(cropped_input_points_d_.get()),
          unique_mask32_d_.get(), unique_indices32_d_.get(), sorted_hash_indexes32_d_.get(),
          reinterpret_cast<CloudPointTypeXYZIRC *>(compact_points), num_cropped_points);
        break;
      case CloudFormat::XYZI:
        extractIndicesKernel<<<num_cropped_blocks, config_.threads_per_block_, 0, stream_>>>(
          reinterpret_cast<CloudPointTypeXYZI *>(cropped_input_points_d_.get()),
          unique_mask32_d_.get(), unique_indices32_d_.get(), sorted_hash_indexes32_d_.get(),
          reinterpret_cast<CloudPointTypeXYZI *>(compact_points), num_cropped_points);
        break;
      default:
        throw std::runtime_error("Unsupported input point cloud format.");
    }
  }

  computeGridCoordsAndSerializationKernel<<<
    num_cropped_blocks, config_.threads_per_block_, 0, stream_>>>(
    reinterpret_cast<float4 *>(voxel_features), reinterpret_cast<longlong3 *>(voxel_coords),
    voxel_hashes, num_unique_points, config_.voxel_x_size_, config_.voxel_y_size_,
    config_.voxel_z_size_, min_x, min_y, min_z, config_.serialization_depth_);

  return num_unique_points;
}

__global__ void points2FeaturesKernel(
  const PointT * __restrict__ input_points, std::size_t points_size,
  float4 * __restrict__ output_points)
{
  const auto idx = static_cast<std::uint32_t>(blockIdx.x * blockDim.x + threadIdx.x);
  if (idx >= points_size) {
    return;
  }

  const PointT & input_point = input_points[idx];
  float4 & output_point = output_points[idx];
  output_point.x = input_point.x;
  output_point.y = input_point.y;
  output_point.z = input_point.z;
  output_point.w = static_cast<float>(input_point.intensity) / 255.f;
}

__global__ void cropKernel(
  float4 * __restrict__ points, std::uint32_t * __restrict__ mask, int num_points, float min_x,
  float min_y, float min_z, float max_x, float max_y, float max_z)
{
  auto idx = static_cast<std::uint32_t>(blockIdx.x * blockDim.x + threadIdx.x);
  if (idx >= num_points) {
    return;
  }
  const float & x = points[idx].x;
  const float & y = points[idx].y;
  const float & z = points[idx].z;

  mask[idx] = x >= min_x && x <= max_x && y >= min_y && y <= max_y && z >= min_z && z <= max_z;
}

__global__ void extractIndicesKernel(
  const scalar_t * __restrict__ input_data, mask_t * __restrict__ masks,
  mask_t * __restrict__ indices, scalar_t * __restrict__ output_data, int num_points)
{
  int idx = blockIdx.x * blockDim.x + threadIdx.x;
  if (idx < num_points && masks[idx] == 1) {
    output_data[indices[idx] - 1] = input_data[idx];
  }
}

__global__ void voxelizationHash64Kernel(
  const float4 * __restrict__ points, std::uint64_t * __restrict__ hashes, int num_points,
  float voxel_size_x, float voxel_size_y, float voxel_size_z, std::int32_t min_x,
  std::int32_t min_y, std::int32_t min_z)
{
  // FNV64-1A
  auto idx = static_cast<std::uint32_t>(blockIdx.x * blockDim.x + threadIdx.x);
  if (idx >= num_points) {
    return;
  }

  const float4 & point = points[idx];
  const auto x = static_cast<std::int32_t>(std::floor(point.x / voxel_size_x));
  const auto y = static_cast<std::int32_t>(std::floor(point.y / voxel_size_y));
  const auto z = static_cast<std::int32_t>(std::floor(point.z / voxel_size_z));

  std::uint64_t hash = 14695981039346656037ULL;
  hash *= 1099511628211ULL;
  hash ^= static_cast<std::uint64_t>(x - min_x);
  hash *= 1099511628211ULL;
  hash ^= static_cast<std::uint64_t>(y - min_y);
  hash *= 1099511628211ULL;
  hash ^= static_cast<std::uint64_t>(z - min_z);

  hashes[idx] = hash;
}

__global__ void computeGridCoordsAndSerializationKernel(
  const float4 * __restrict__ points, longlong3 * __restrict__ coords,
  std::int64_t * __restrict__ hashes, int num_points, float voxel_size_x, float voxel_size_y,
  float voxel_size_z, std::int32_t min_x, std::int32_t min_y, std::int32_t min_z, int depth)
{
  static_assert(sizeof(longlong3) == sizeof(std::uint64_t) * 3, "longlong3 must be 24 bytes");
  auto idx = static_cast<std::uint32_t>(blockIdx.x * blockDim.x + threadIdx.x);
  if (idx >= num_points) {
    return;
  }

  const float4 & point = points[idx];
  const std::int64_t x = static_cast<std::int32_t>(std::floor(point.x / voxel_size_x) - min_x);
  const std::int64_t y = static_cast<std::int32_t>(std::floor(point.y / voxel_size_y) - min_y);
  const std::int64_t z = static_cast<std::int32_t>(std::floor(point.z / voxel_size_z) - min_z);

  coords[idx] = make_longlong3(x, y, z);

  std::int64_t key1 = 0;
  std::int64_t key2 = 0;

  for (int i = 0; i < depth; ++i) {
    std::int64_t mask = 1 << i;
    key1 |= ((x & mask) << (2 * i + 2));
    key1 |= ((y & mask) << (2 * i + 1));
    key1 |= ((z & mask) << (2 * i + 0));

    key2 |= ((y & mask) << (2 * i + 2));
    key2 |= ((x & mask) << (2 * i + 1));
    key2 |= ((z & mask) << (2 * i + 0));
  }

  hashes[idx] = key1;
  hashes[idx + num_points] = key2;
}

bool TrtCommon::setInputShape(const char * tensor_name, const nvinfer1::Dims & dimensions)
{
  if (!context_) {
    logger_->log(nvinfer1::ILogger::Severity::kERROR, "Context is not initialized");
    return false;
  }
  auto success = context_->setInputShape(tensor_name, dimensions);
  if (!success) {
    logger_->log(
      nvinfer1::ILogger::Severity::kERROR, "Failed to set input shape for tensor: ", tensor_name);
  }
  return success;
}

bool PTv3TRT::inference()
{
  auto status = network_trt_ptr_->enqueueV3(stream_);
  CHECK_CUDA_ERROR(cudaStreamSynchronize(stream_));

  if (!status) {
    RCLCPP_ERROR(rclcpp::get_logger("ptv3"), "Fail to enqueue and skip to detect.");
    return false;
  }

  return true;
}

bool TrtCommon::enqueueV3(cudaStream_t stream)
{
  if (!context_) {
    logger_->log(nvinfer1::ILogger::Severity::kERROR, "Context is not initialized");
    return false;
  }
  if (trt_config_->profile_per_layer) {
    auto inference_start = std::chrono::high_resolution_clock::now();
    auto success = context_->enqueueV3(stream);
    auto inference_end = std::chrono::high_resolution_clock::now();
    host_profiler_->reportLayerTime(
      "inference_host",
      std::chrono::duration<float, std::milli>(inference_end - inference_start).count());
    return success;
  }
  return context_->enqueueV3(stream);
}

bool enqueueV3(cudaStream_t stream) noexcept
{
    return mImpl->enqueueV3(stream);
}

bool PTv3TRT::postProcess(
  const std_msgs::msg::Header & header, bool should_publish_segmented_pointcloud,
  bool should_publish_visualization_pointcloud, bool should_publish_filtered_pointcloud)
{
  // Segmentation pointcloud
  if (should_publish_segmented_pointcloud) {
    post_ptr_->createSegmentationPointcloud(
      feat_d_.get(), pred_labels_d_.get(), pred_probs_d_.get(),
      segmented_points_msg_ptr_->data.get(), config_.class_names_.size(), num_voxels_);
    CHECK_CUDA_ERROR(cudaStreamSynchronize(stream_));

    segmented_points_msg_ptr_->header = header;
    segmented_points_msg_ptr_->width = num_voxels_;
    publish_segmented_pointcloud_(std::move(segmented_points_msg_ptr_));
    segmented_points_msg_ptr_ = nullptr;
  }

  // Visualization pointcloud
  if (should_publish_visualization_pointcloud) {
    post_ptr_->createVisualizationPointcloud(
      feat_d_.get(), pred_labels_d_.get(),
      reinterpret_cast<float *>(visualization_points_msg_ptr_->data.get()), num_voxels_);
    CHECK_CUDA_ERROR(cudaStreamSynchronize(stream_));
    visualization_points_msg_ptr_->header = header;
    visualization_points_msg_ptr_->width = num_voxels_;
    publish_visualization_pointcloud_(std::move(visualization_points_msg_ptr_));
    visualization_points_msg_ptr_ = nullptr;
  }

  if (should_publish_filtered_pointcloud) {
    const auto num_filtered_points = post_ptr_->createFilteredPointcloud(
      compact_points_d_.get(), input_format_, filtered_output_format_, pred_probs_d_.get(),
      filtered_points_msg_ptr_->data.get(), config_.class_names_.size(), num_voxels_);
    CHECK_CUDA_ERROR(cudaStreamSynchronize(stream_));

    filtered_points_msg_ptr_->header = header;
    filtered_points_msg_ptr_->width = num_filtered_points;
    publish_filtered_pointcloud_(std::move(filtered_points_msg_ptr_));
    filtered_points_msg_ptr_ = nullptr;
  }

  allocateMessages();
  return true;
}

void PostprocessCuda::createSegmentationPointcloud(
  const float * input_features, const std::int64_t * pred_labels, const float * pred_probs,
  std::uint8_t * output_points, std::size_t num_classes, std::size_t num_points)
{
  auto num_blocks = divup(num_points, config_.threads_per_block_);

  createSegmentationPointcloudKernel<<<num_blocks, config_.threads_per_block_, 0, stream_>>>(
    reinterpret_cast<const float4 *>(input_features), pred_labels, pred_probs,
    reinterpret_cast<OutputSegmentationPointType *>(output_points), num_classes, num_points);

  CHECK_CUDA_ERROR(cudaStreamSynchronize(stream_));
}

__global__ void createSegmentationPointcloudKernel(
  const float4 * input_features, const std::int64_t * labels, const float * pred_probs,
  OutputSegmentationPointType * output_points, std::size_t num_classes, std::size_t num_points)
{
  const auto idx = static_cast<std::uint32_t>(blockIdx.x * blockDim.x + threadIdx.x);
  if (idx >= num_points) {
    return;
  }

  const auto input_point = input_features[idx];
  const auto label = labels[idx];
  output_points[idx].x = input_point.x;
  output_points[idx].y = input_point.y;
  output_points[idx].z = input_point.z;
  output_points[idx].class_id = static_cast<std::uint8_t>(label);
  output_points[idx].probability = pred_probs[idx * num_classes + label];
}

void PostprocessCuda::createVisualizationPointcloud(
  const float * input_features, const std::int64_t * labels, float * output_points,
  std::size_t num_points)
{
  auto num_blocks = divup(num_points, config_.threads_per_block_);

  createVisualizationPointcloudKernel<<<num_blocks, config_.threads_per_block_, 0, stream_>>>(
    reinterpret_cast<const float4 *>(input_features), color_map_d_.get(), labels,
    reinterpret_cast<float4 *>(output_points), num_points);

  CHECK_CUDA_ERROR(cudaStreamSynchronize(stream_));
}

__global__ void createVisualizationPointcloudKernel(
  const float4 * input_features, const float * colors, const std::int64_t * labels,
  float4 * output_points, std::size_t num_points)
{
  const auto idx = static_cast<std::uint32_t>(blockIdx.x * blockDim.x + threadIdx.x);
  if (idx >= num_points) {
    return;
  }

  const auto label = labels[idx];
  const auto color = colors[label];

  output_points[idx] =
    make_float4(input_features[idx].x, input_features[idx].y, input_features[idx].z, color);
}

std::size_t PostprocessCuda::createFilteredPointcloud(
  const void * compact_input_points, CloudFormat input_format, CloudFormat output_format,
  const float * pred_probs, void * output_points, std::size_t num_classes, std::size_t num_points)
{
  cudaMemsetAsync(filtered_mask_d_.get(), 0, sizeof(std::uint32_t), stream_);

  switch (input_format) {
    case CloudFormat::XYZIRCAEDT:
      switch (output_format) {
        case CloudFormat::XYZIRCAEDT:
          createFilteredPointcloudTyped<CloudPointTypeXYZIRCAEDT, CloudPointTypeXYZIRCAEDT>(
            stream_, config_.threads_per_block_, compact_input_points, pred_probs,
            filter_class_indices_d_.get(), config_.filter_class_indices_.size(),
            config_.filter_class_probability_threshold_, num_classes, filtered_mask_d_.get(),
            output_points, num_points);
          break;
        case CloudFormat::XYZIRC:
          createFilteredPointcloudTyped<CloudPointTypeXYZIRCAEDT, CloudPointTypeXYZIRC>(
            stream_, config_.threads_per_block_, compact_input_points, pred_probs,
            filter_class_indices_d_.get(), config_.filter_class_indices_.size(),
            config_.filter_class_probability_threshold_, num_classes, filtered_mask_d_.get(),
            output_points, num_points);
          break;
        case CloudFormat::XYZI:
          createFilteredPointcloudTyped<CloudPointTypeXYZIRCAEDT, CloudPointTypeXYZI>(
            stream_, config_.threads_per_block_, compact_input_points, pred_probs,
            filter_class_indices_d_.get(), config_.filter_class_indices_.size(),
            config_.filter_class_probability_threshold_, num_classes, filtered_mask_d_.get(),
            output_points, num_points);
          break;
        default:
          throw std::runtime_error("Unsupported filtered output format.");
      }
      break;
    case CloudFormat::XYZIRADRT:
      switch (output_format) {
        case CloudFormat::XYZIRADRT:
          createFilteredPointcloudTyped<CloudPointTypeXYZIRADRT, CloudPointTypeXYZIRADRT>(
            stream_, config_.threads_per_block_, compact_input_points, pred_probs,
            filter_class_indices_d_.get(), config_.filter_class_indices_.size(),
            config_.filter_class_probability_threshold_, num_classes, filtered_mask_d_.get(),
            output_points, num_points);
          break;
        case CloudFormat::XYZI:
          createFilteredPointcloudTyped<CloudPointTypeXYZIRADRT, CloudPointTypeXYZI>(
            stream_, config_.threads_per_block_, compact_input_points, pred_probs,
            filter_class_indices_d_.get(), config_.filter_class_indices_.size(),
            config_.filter_class_probability_threshold_, num_classes, filtered_mask_d_.get(),
            output_points, num_points);
          break;
        default:
          throw std::runtime_error("Unsupported filtered output format.");
      }
      break;
    case CloudFormat::XYZIRC:
      switch (output_format) {
        case CloudFormat::XYZIRC:
          createFilteredPointcloudTyped<CloudPointTypeXYZIRC, CloudPointTypeXYZIRC>(
            stream_, config_.threads_per_block_, compact_input_points, pred_probs,
            filter_class_indices_d_.get(), config_.filter_class_indices_.size(),
            config_.filter_class_probability_threshold_, num_classes, filtered_mask_d_.get(),
            output_points, num_points);
          break;
        case CloudFormat::XYZI:
          createFilteredPointcloudTyped<CloudPointTypeXYZIRC, CloudPointTypeXYZI>(
            stream_, config_.threads_per_block_, compact_input_points, pred_probs,
            filter_class_indices_d_.get(), config_.filter_class_indices_.size(),
            config_.filter_class_probability_threshold_, num_classes, filtered_mask_d_.get(),
            output_points, num_points);
          break;
        default:
          throw std::runtime_error("Unsupported filtered output format.");
      }
      break;
    case CloudFormat::XYZI:
      if (output_format != CloudFormat::XYZI) {
        throw std::runtime_error("Unsupported filtered output format.");
      }
      createFilteredPointcloudTyped<CloudPointTypeXYZI, CloudPointTypeXYZI>(
        stream_, config_.threads_per_block_, compact_input_points, pred_probs,
        filter_class_indices_d_.get(), config_.filter_class_indices_.size(),
        config_.filter_class_probability_threshold_, num_classes, filtered_mask_d_.get(),
        output_points, num_points);
      break;
    default:
      throw std::runtime_error("Unsupported input point cloud format.");
  }

  std::uint32_t num_filtered_points = 0;
  cudaMemcpyAsync(
    &num_filtered_points, filtered_mask_d_.get(), sizeof(std::uint32_t), cudaMemcpyDeviceToHost,
    stream_);
  CHECK_CUDA_ERROR(cudaStreamSynchronize(stream_));
  return num_filtered_points;
}

void createFilteredPointcloudTyped(
  cudaStream_t stream, std::uint32_t threads_per_block, const void * compact_input_points,
  const float * pred_probs, const std::uint32_t * filter_class_indices,
  std::size_t num_filter_classes, float filter_class_probability_threshold, std::size_t num_classes,
  std::uint32_t * output_num_points, void * output_points, std::size_t num_points)
{
  const auto num_blocks = divup(num_points, threads_per_block);
  createFilteredPointcloudKernel<<<num_blocks, threads_per_block, 0, stream>>>(
    static_cast<const InputPointT *>(compact_input_points), pred_probs, filter_class_indices,
    num_filter_classes, filter_class_probability_threshold, num_classes, output_num_points,
    static_cast<OutputPointT *>(output_points), num_points);
}

__global__ void createFilteredPointcloudKernel(
  const InputPointT * input_points, const float * pred_probs,
  const std::uint32_t * filter_class_indices, std::size_t num_filter_classes,
  float filter_class_probability_threshold, std::size_t num_classes,
  std::uint32_t * output_num_points, OutputPointT * output_points, std::size_t num_points)
{
  const auto idx = static_cast<std::uint32_t>(blockIdx.x * blockDim.x + threadIdx.x);
  if (idx >= num_points) {
    return;
  }

  bool keep_point = true;
  const float * point_probs = &pred_probs[num_classes * idx];
  for (std::size_t i = 0; i < num_filter_classes; ++i) {
    const auto class_idx = filter_class_indices[i];
    if (point_probs[class_idx] >= filter_class_probability_threshold) {
      keep_point = false;
      break;
    }
  }

  if (!keep_point) {
    return;
  }

  const auto output_idx = atomicAdd(output_num_points, 1U);
  set_point_from_input(output_points[output_idx], input_points[idx]);
}

__device__ void set_point_from_input(
  OutputPointT & output_point, const CloudPointTypeXYZI & input_point);
template <typename OutputPointT>
__device__ void set_point_from_input(
  OutputPointT & output_point, const CloudPointTypeXYZIRC & input_point);
template <typename OutputPointT>
__device__ void set_point_from_input(
  OutputPointT & output_point, const CloudPointTypeXYZIRADRT & input_point);
template <typename OutputPointT>
__device__ void set_point_from_input(
  OutputPointT & output_point, const CloudPointTypeXYZIRCAEDT & input_point);

template <>
__device__ void set_point_from_input<CloudPointTypeXYZI>(
  CloudPointTypeXYZI & output_point, const CloudPointTypeXYZI & input_point)
{
  output_point = input_point;
}

void PTv3TRT::allocateMessages()
{
  if (segmented_points_msg_ptr_ == nullptr) {
    segmented_points_msg_ptr_ = std::make_unique<cuda_blackboard::CudaPointCloud2>();
    segmented_points_msg_ptr_->height = 1;
    segmented_points_msg_ptr_->width = config_.max_num_voxels_;
    segmented_points_msg_ptr_->fields = segmented_pointcloud_fields_;
    segmented_points_msg_ptr_->is_bigendian = false;
    segmented_points_msg_ptr_->is_dense = true;
    segmented_points_msg_ptr_->point_step = 17U;
    segmented_points_msg_ptr_->data = cuda_blackboard::make_unique<std::uint8_t[]>(
      config_.max_num_voxels_ * segmented_points_msg_ptr_->point_step);
  }

  if (visualization_points_msg_ptr_ == nullptr) {
    visualization_points_msg_ptr_ = std::make_unique<cuda_blackboard::CudaPointCloud2>();
    visualization_points_msg_ptr_->height = 1;
    visualization_points_msg_ptr_->width = config_.max_num_voxels_;
    visualization_points_msg_ptr_->fields = visualization_pointcloud_fields_;
    visualization_points_msg_ptr_->is_bigendian = false;
    visualization_points_msg_ptr_->is_dense = true;
    visualization_points_msg_ptr_->point_step =
      static_cast<std::uint32_t>(visualization_pointcloud_fields_.size() * sizeof(float));
    visualization_points_msg_ptr_->data = cuda_blackboard::make_unique<std::uint8_t[]>(
      config_.max_num_voxels_ * visualization_points_msg_ptr_->point_step);
  }

  if (filtered_points_msg_ptr_ == nullptr && filtered_output_format_ != CloudFormat::UNKNOWN) {
    filtered_points_msg_ptr_ = std::make_unique<cuda_blackboard::CudaPointCloud2>();
    filtered_points_msg_ptr_->height = 1;
    filtered_points_msg_ptr_->width = config_.max_num_voxels_;
    filtered_points_msg_ptr_->fields = filtered_pointcloud_fields_;
    filtered_points_msg_ptr_->is_bigendian = false;
    filtered_points_msg_ptr_->is_dense = true;
    filtered_points_msg_ptr_->point_step =
      static_cast<std::uint32_t>(get_point_step(filtered_output_format_));
    filtered_points_msg_ptr_->data = cuda_blackboard::make_unique<std::uint8_t[]>(
      config_.max_num_voxels_ * filtered_points_msg_ptr_->point_step);
  }
}
